import { DsLink } from '@primasoftllc/design-system';

export function Example() {
  const pageUrl = typeof window === 'undefined' ? '' : window.location.href.split('#')[0];
  return <div style={{display: 'grid', gap: 16}}>
    <p style={{margin: 0}}>Задайте получателей и частоту доставки. <DsLink href={pageUrl + '#notification-settings'}>К настройкам уведомлений</DsLink></p>
    <section id="notification-settings" tabIndex={-1} aria-label="Настройки уведомлений">
      <strong>Настройки уведомлений</strong>
      <p style={{margin: '8px 0 0'}}>События доставляются дежурному диспетчеру по электронной почте.</p>
    </section>
  </div>;
}

